// Fuzz ProtFlag bitwise-OR and validate algebraic properties without relying on other overloads
// Generate two random, valid ProtFlag bitmasks. Valid bits are: X(1<<1), R(1<<2), W(1<<3), S(1<<4), P(1<<5), NONE(1<<6). UNSET is 0.
uint8_t rawA = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x7E); // keep bits 1..6
uint8_t rawB = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x7E);

// Construct composite ProtFlag values directly from integers to avoid invoking operator| during setup
PLH::ProtFlag lhs = static_cast<PLH::ProtFlag>(rawA);
PLH::ProtFlag rhs = static_cast<PLH::ProtFlag>(rawB);

// Invoke target function
PLH::ProtFlag out1 = PLH::operator|(lhs, rhs);

// Basic identities and algebraic properties
// Idempotent: a | a == a
PLH::ProtFlag selfOr = PLH::operator|(lhs, lhs);
FUZZ_ASSERT((uint8_t)selfOr == (uint8_t)lhs, "ProtFlag OR idempotency failed");

// Identity element: a | UNSET == a
PLH::ProtFlag unset = static_cast<PLH::ProtFlag>(0);
PLH::ProtFlag idOr = PLH::operator|(lhs, unset);
FUZZ_ASSERT((uint8_t)idOr == (uint8_t)lhs, "ProtFlag OR identity with UNSET failed");

// Commutativity: a | b == b | a
PLH::ProtFlag out2 = PLH::operator|(rhs, lhs);
FUZZ_ASSERT((uint8_t)out1 == (uint8_t)out2, "ProtFlag OR commutativity failed");

// Distribute membership: for selected basis flags f, (lhs|rhs) contains f iff lhs contains f or rhs contains f
// We use operator&(ProtFlag, ProtFlag)->bool to test membership.
auto contains = [](PLH::ProtFlag a, PLH::ProtFlag f)->bool { return PLH::operator&(a, f); };

PLH::ProtFlag fX = static_cast<PLH::ProtFlag>(1u<<1);
PLH::ProtFlag fR = static_cast<PLH::ProtFlag>(1u<<2);
PLH::ProtFlag fW = static_cast<PLH::ProtFlag>(1u<<3);
PLH::ProtFlag fS = static_cast<PLH::ProtFlag>(1u<<4);
PLH::ProtFlag fP = static_cast<PLH::ProtFlag>(1u<<5);

bool resX = contains(out1, fX);
bool wantX = contains(lhs, fX) || contains(rhs, fX);
FUZZ_ASSERT(resX == wantX, "ProtFlag OR membership for X failed");

bool resR = contains(out1, fR);
bool wantR = contains(lhs, fR) || contains(rhs, fR);
FUZZ_ASSERT(resR == wantR, "ProtFlag OR membership for R failed");

bool resW = contains(out1, fW);
bool wantW = contains(lhs, fW) || contains(rhs, fW);
FUZZ_ASSERT(resW == wantW, "ProtFlag OR membership for W failed");

bool resS = contains(out1, fS);
bool wantS = contains(lhs, fS) || contains(rhs, fS);
FUZZ_ASSERT(resS == wantS, "ProtFlag OR membership for S failed");

bool resP = contains(out1, fP);
bool wantP = contains(lhs, fP) || contains(rhs, fP);
FUZZ_ASSERT(resP == wantP, "ProtFlag OR membership for P failed");

// No persistent inputs or outputs to return; purely functional test

// Fuzz ProtFlag bitwise-AND (boolean test) and validate semantics
// Valid bits: X(1<<1), R(1<<2), W(1<<3), S(1<<4), P(1<<5), NONE(1<<6); UNSET is 0.
uint8_t rawA = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x7E);
uint8_t rawB = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0x7E);

PLH::ProtFlag a = static_cast<PLH::ProtFlag>(rawA);
PLH::ProtFlag b = static_cast<PLH::ProtFlag>(rawB);

// Invoke target function
bool interAB = PLH::operator&(a, b);

// Ground truth using integer masks: true iff any common bit is set
bool expect = (rawA & rawB) != 0;
FUZZ_ASSERT(interAB == expect, "ProtFlag AND boolean mismatch with mask expectation");

// Commutativity of intersection
bool interBA = PLH::operator&(b, a);
FUZZ_ASSERT(interAB == interBA, "ProtFlag AND commutativity failed");

// AND with UNSET is always false
PLH::ProtFlag unset = static_cast<PLH::ProtFlag>(0);
bool interUnset = PLH::operator&(a, unset);
FUZZ_ASSERT(interUnset == false, "ProtFlag AND with UNSET should be false");

// Spot-check: if we pick a single-bit flag present in both, result must be true; otherwise may be false
// Select a single bit from the overlap or from a to probe behavior deterministically
uint8_t overlap = (uint8_t)(rawA & rawB & 0x7E);
if (overlap != 0) {
    // choose the lowest set bit in overlap
    uint8_t bit = (uint8_t)(overlap & (uint8_t)(-((int8_t)overlap)));
    PLH::ProtFlag f = static_cast<PLH::ProtFlag>(bit);
    bool chk = PLH::operator&(PLH::operator|(a, unset), f) && PLH::operator&(b, f);
    FUZZ_ASSERT(chk == true, "ProtFlag AND should detect shared single-bit flag");
}

