import random
from typing import List

def _gen_exact_match(n: int, rng: random.Random) -> bytes:
    # Create a random buffer and we expect the fuzzer to derive pat from it modulo 255 + 1.
    # To maximize exact matches when mask has 'x', ensure buf bytes are in 1..255 range
    # so (rb % 255) + 1 equals rb for 1..254, but 255 maps to 1, 0 maps to 1.
    # We avoid 0 to keep C-strings safe and avoid 255 to not remap to 1.
    return bytes(rng.randrange(1, 255) for _ in range(n))

def _gen_repeating(n: int, rng: random.Random) -> bytes:
    # Repeating patterns help expose mask wildcards and matching logic
    choices = [b"A", b"B", b"\x01", b"\x7F", b"\x80", b"\xFE"]
    pat = rng.choice(choices)
    return (pat * (n // len(pat) + 1))[:n]

def _gen_incremental(n: int, start: int) -> bytes:
    # Ascending bytes in 1..254 range to keep mapping stable
    data = bytearray(n)
    v = start % 254 + 1
    for i in range(n):
        data[i] = v
        v += 1
        if v >= 255:
            v = 1
    return bytes(data)

def _gen_edge_bytes(n: int) -> bytes:
    # Mix of edge values avoiding 0 for C-string safety in pattern construction
    edges: List[int] = [1, 2, 3, 0x7F, 0x80, 0xFE, 0xF0, 0x10, 0x20, 0x41, 0xAA, 0x55]
    out = bytearray()
    i = 0
    while len(out) < n:
        out.append(edges[i % len(edges)])
        i += 1
    return bytes(out[:n])

def _gen_alternating(n: int, a: int, b: int) -> bytes:
    a = 1 if a % 255 == 0 else a % 256
    b = 1 if b % 255 == 0 else b % 256
    data = bytearray(n)
    for i in range(n):
        data[i] = a if (i & 1) == 0 else b
    return bytes(data)

def _choose_length(rng: random.Random) -> int:
    # The stub caps n to 1..256; choose biased lengths including boundaries
    weighted = [1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256]
    if rng.random() < 0.7:
        return rng.choice(weighted)
    return rng.randint(1, 256)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    n = _choose_length(rng)

    # Select a strategy to create a buffer that will tend to yield valid matches
    strat = rng.random()
    if strat < 0.25:
        buf = _gen_exact_match(n, rng)
    elif strat < 0.45:
        buf = _gen_repeating(n, rng)
    elif strat < 0.7:
        buf = _gen_incremental(n, rng.randrange(0, 1000))
    elif strat < 0.9:
        buf = _gen_alternating(n, rng.randrange(1, 255), rng.randrange(1, 255))
    else:
        buf = _gen_edge_bytes(n)

    # Ensure size constraint and return
    return bytes(buf[:4096])
